package africa.fyrebox.fyrebox_technician;
import android.app.Activity;import android.content.Intent;import android.net.Uri;import android.os.Bundle;import android.webkit.*;import java.io.*;import java.util.HashMap;
public class ScannerActivity extends Activity{private WebView web;private boolean finished;@Override public void onCreate(Bundle s){super.onCreate(s);web=new WebView(this);setContentView(web);web.getSettings().setJavaScriptEnabled(true);web.getSettings().setAllowFileAccess(false);web.getSettings().setAllowContentAccess(false);web.getSettings().setMediaPlaybackRequiresUserGesture(false);web.addJavascriptInterface(new Object(){@JavascriptInterface public void found(String q){if(q==null||q.length()>4096)return;runOnUiThread(()->{if(finished)return;finished=true;setResult(RESULT_OK,new Intent().putExtra("qr",q));finish();});}@JavascriptInterface public void close(){runOnUiThread(()->finish());}},"Scanner");web.setWebViewClient(new WebViewClient(){@Override public boolean shouldOverrideUrlLoading(WebView w,WebResourceRequest r){return true;}@Override public WebResourceResponse shouldInterceptRequest(WebView w,WebResourceRequest r){Uri u=r.getUrl();if(!"scanner.fyrebox.local".equals(u.getHost())||!"https".equals(u.getScheme()))return empty();String f=u.getPath();if(!"/index.html".equals(f)&&!"/jsQR.js".equals(f))return empty();try{HashMap<String,String> h=new HashMap<>();h.put("Content-Security-Policy","default-src 'none'; script-src 'self' 'unsafe-inline'; style-src 'unsafe-inline'; media-src blob:; connect-src 'self'");return new WebResourceResponse(f.endsWith(".js")?"application/javascript":"text/html","UTF-8",200,"OK",h,getAssets().open("scanner"+f));}catch(Exception ex){return empty();}}});web.setWebChromeClient(new WebChromeClient(){@Override public void onPermissionRequest(PermissionRequest r){runOnUiThread(()->{if("scanner.fyrebox.local".equals(r.getOrigin().getHost()))r.grant(new String[]{PermissionRequest.RESOURCE_VIDEO_CAPTURE});else r.deny();});}});web.loadUrl("https://scanner.fyrebox.local/index.html");}private WebResourceResponse empty(){return new WebResourceResponse("text/plain","UTF-8",new ByteArrayInputStream(new byte[0]));}@Override protected void onPause(){if(web!=null)web.evaluateJavascript("stopCamera()",null);super.onPause();}@Override protected void onDestroy(){if(web!=null){web.removeJavascriptInterface("Scanner");web.destroy();}super.onDestroy();}}
